def f(g):
    from collections import Counter
    c=Counter(x for r in g for x in r)
    maj=c.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=maj:
                nb=[(i+di,j+dj) for di,dj in((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+di<h and 0<=j+dj<w]
                if all(g[a][b]==maj for a,b in nb):
                    out[i][j]=2
    return out
